jsxGraph.script:
board.suspendUpdate();
board.create('arrow', [[-2.5,0], [8.5,0]], {strokeColor: 'black', strokeWidth: 1});
board.create('arrow', [[0,-4.5], [0,7.5]], {strokeColor: 'black', strokeWidth: 1});
board.create('text', [8.3, -0.4, 'x'], {fontSize: 14});
board.create('text', [-0.4, 7.2, 'y'], {fontSize: 14});
board.create('functiongraph', [function(x){ return Math.pow(x-3, 2) - 4; }], {strokeColor: '#4f46e5', strokeWidth: 1.5});
board.create('point', [3, -4], {name: 'V(3,-4)', visible: true, strokeColor: '#4f46e5', label: {autoPosition: false, offset: [0, 10]}});
board.create('point', [0, 5], {name: '(0,5)', visible: true, strokeColor: '#4f46e5', label: {autoPosition: false, offset: [0, 10]}});
board.create('point', [1, 0], {name: '1', visible: true, strokeColor: '#4f46e5', label: {autoPosition: false, offset: [0, 10]}});
board.create('point', [5, 0], {name: '5', visible: true, strokeColor: '#4f46e5', label: {autoPosition: false, offset: [0, 10]}});
board.create('line', [[3,-5], [3,8]], {strokeColor: '#64748b', dash: 2, strokeWidth: 1});
board.unsuspendUpdate();

board.suspendUpdate();
board.create('arrow', [[-2.5,0], [6.5,0]], {strokeColor: 'black', strokeWidth: 1});
board.create('arrow', [[0,-1.5], [0,5.5]], {strokeColor: 'black', strokeWidth: 1});
board.create('text', [6.3, -0.4, 'x'], {fontSize: 14});
board.create('text', [-0.4, 5.2, 'y'], {fontSize: 14});
board.create('functiongraph', [function(x){ return -Math.pow(x-2, 2) + 4; }], {strokeColor: '#4f46e5', strokeWidth: 1.5});
board.create('point', [2, 4], {name: 'V(2,4)', visible: true, strokeColor: '#4f46e5', label: {autoPosition: false, offset: [0, 10]}});
board.create('point', [0, 0], {name: 'O', visible: true, strokeColor: '#4f46e5', label: {autoPosition: false, offset: [0, 10]}});
board.create('point', [4, 0], {name: '4', visible: true, strokeColor: '#4f46e5', label: {autoPosition: false, offset: [0, 10]}});
board.create('line', [[2,-2], [2,6]], {strokeColor: '#64748b', dash: 2, strokeWidth: 1});
board.unsuspendUpdate();
